import json
N="""IRIM SINGULAR ENNUST USTIR UNARA HADUPHIS BUSIM RURIUS JOINUM BAX ROTHYR MARDOM HIZZEL WEZEN KOTER BAESTA LISHVAL CIDAR DRISK GORIM FURUD TIUZ TIRIYOK BEID HLIIJE TARGON GEULEA AIASTAR ENKET SIGMA_DRACONIS OKUL ZAFFA CUUNBAR MITHAR KONGATH QUANNAGA ELDERAK HIKLAM UHGRONE HADRICCUS ASMORE EIEOSPONE GRUMIUM SORCIMAX ULDOR IMDAR FIGZAR ACRAMATO HAVONCHIR EPSILON_ERIDANI GRIBBON JAPHON WANAMBUS DASTAMON MECURA FEVALLION DERELLIS VANNIKO THIRIMORA GINNOG CHURASSIX LYTIRIM DAARASTA TORROM BARBAN MATAR FUYE ARAUSNYRIA SCIPITON UZUN GERONTH HIXAM MAASYM THAARAM JILLIS APPON ZARQON MUBBLAR APHRIS GAMMA_DRACONIS SADATONI WIR_THOSK TIQIM NIXAHEL ALVYZRA ROMSTON SIRIUS BAL_DURK DARANMA GEQIETUM ANACHONUS GEDEXUS CAZZABIUS TIRIM TADASCA FEJANTRIS MYRUM CHELEB SOL DUHR TOROVIL WICKLAR SAONUS TEM SHASHAMAR HEMTARES ROVGEDDI ALPHA_CENTAURI OVASTIUUM NOMOTAR POLARIS POLYMAR PROCYON TALANDRA BASHPIT MAWEER ERIGA WUAE BRINK TETHELL HOWOZ PHONOK IZAR ZOM KASTABA IJAX KAZOO BINAMI SABIK CRAXIMA CIRBAN FAENOV HYDROBIUS HAEDUS ROVANNIC YILDUN FIR_MATHRIOZ AJAM ETHEEN GUHUR OSELLUS KASTRA STIRIDON LADIOM YIRBA TRAB HOCRY GOLBA SAOLEA ZOSMA DURASCADON HALAX ESMYKE HOEDDIM TAGGALION MEDIA ELLAMIR LEESAK SWUR AZAK XIMPOK PONNELL UTHAN VEYER CEYECARRO BATRAQ ROSCHON AETHOS GALURUM HHABBAN NITHASCAL KSORA BRALLIX BANAGHO FEONUS UMIK ACHERNAR OMAGGUS DOTHOM BETA_AQUILAE KUMA VELDERAAM DATE1 DATE2 IJAAGIN CINE FOLINGAR SIPLIM QAD_VHI DIMIS MOREGARD TEYTERA AMPAL_DIR""".split()
S=json.load(open('systems_ocr.json'))
assert len(N)==len(S),(len(N),len(S))
extra=[(4944,2512,'BARNARDS_STAR'),(1599,2677,'SPICA'),(2724,3592,'EXEDOR')]
comp=json.load(open('extra.json'))
out=[]
for n,s in zip(N,S):
    if n.startswith('DATE'): continue
    out.append({'name':n,'x':s['x'],'y':s['y'],'pts':s['pts']})
for x,y,n in extra: out.append({'name':n,'x':x,'y':y,'pts':[(x,y)]})
# companions
for c in comp:
    if any(abs(c[0]-e[0])<3 and abs(c[1]-e[1])<3 for e in extra): continue
    s=min(out,key=lambda s:(s['x']-c[0])**2+(s['y']-c[1])**2); s['pts'].append((c[0],c[1]))
def title(n):
    t=n.replace('_',' ').title()
    return {'Ijax':'Ijax','Barnards Star':"Barnard's Star",'Ijaagin':'Ijaagin','Qad Vhi':'Qad Vhi','Wir Thosk':'Wir Thosk','Bal Durk':'Bal Durk','Ampal Dir':'Ampal Dir'}.get(t,t)
for s in out: s['name']=title(s['name'])
print(len(out))
json.dump(out,open('systems_named.json','w'),indent=0)
